export interface ProcedureRow {
  name: string;
  tooth: string;
  price: number;
}

export function cleanNotes(notes?: string): string {
  if (!notes) return '';
  let str = notes;

  // Remove redundant boilerplate prefixes generated by system
  str = str.replace(/جلسة علاجية على الضرس\s*#?\d+\s*(\([^\)]*\))?\s*:\s*/gi, ' ');
  str = str.replace(/جلسة علاجية من الطبيب\s*:\s*/gi, ' ');
  str = str.replace(/حساب زيارة كشف مباشر\s*:\s*/gi, ' ');
  str = str.replace(/تم إضافة جلسة إضافية من الطبيب وإرسالها للاستقبال للتحصيل\.?/gi, ' ');
  str = str.replace(/تم إضافة جلسة إضافية من ملف المريض\.?/gi, ' ');

  // Clean up any empty lines or leading/trailing whitespace
  const lines = str
    .split('\n')
    .map(l => l.trim())
    .filter(l => l && !l.startsWith('[تم سداد'));

  return lines.join('\n').trim();
}

const STANDARD_EGP_PRICES: Record<string, number> = {
  'كشف عام وفحص أولى': 200,
  'كشف عام': 200,
  'تنظيف وتلميع أسنان': 400,
  'تنظيف أسنان': 400,
  'حشو تجميلي (ليزر)': 500,
  'حشو تجميلي': 500,
  'علاج عصب (حشو جذور)': 800,
  'علاج عصب': 800,
  'خلع سن/ضرس بسيط': 300,
  'خلع سن/ضرس': 300,
  'خلع جراحي': 700,
  'خلع ضرس عقل جراحي': 700,
  'تركيب تاج بورسلين أو زيركون': 1200,
  'تركيب تاج/بورسلين': 1200,
  'زراعة أسنان': 5000,
  'جلسة تقويم أسنان دورية': 1000,
  'تقويم أسنان': 1000,
  'تبييض الأسنان': 1500,
  'تبييض كيميائي/منزلي': 1500,
  'جلسة علاجية': 300
};

export interface ToothInfo {
  raw: string | number;
  isChild: boolean;
  fdi: string;
  palmerLetter: string;
  quadrant: 'UR' | 'UL' | 'LL' | 'LR' | null;
  palmerSymbol: string;
  borderClass: string;
  displayFormatted: string;
  fullText: string;
}

export function getToothInfo(num: number | string | null | undefined): ToothInfo {
  if (num === null || num === undefined || num === '') {
    return {
      raw: '',
      isChild: false,
      fdi: '',
      palmerLetter: '',
      quadrant: null,
      palmerSymbol: '',
      borderClass: '',
      displayFormatted: '',
      fullText: ''
    };
  }

  const rawStr = String(num).trim();
  const n = Number(rawStr);

  // 1. Chart internal child numbers 101-120
  if (!isNaN(n) && n >= 101 && n <= 120) {
    let fdi = '';
    let palmerLetter = '';
    let quadrant: 'UR' | 'UL' | 'LL' | 'LR' = 'UR';
    let palmerSymbol = '┘';
    let borderClass = 'border-b-2 border-r-2';

    if (n >= 101 && n <= 105) {
      quadrant = 'UR';
      fdi = (56 - (n - 100)).toString();
      palmerLetter = String.fromCharCode(65 + (105 - n));
      palmerSymbol = '┘';
      borderClass = 'border-b-2 border-r-2';
    } else if (n >= 106 && n <= 110) {
      quadrant = 'UL';
      fdi = (61 + (n - 106)).toString();
      palmerLetter = String.fromCharCode(65 + (n - 106));
      palmerSymbol = '└';
      borderClass = 'border-b-2 border-l-2';
    } else if (n >= 111 && n <= 115) {
      quadrant = 'LL';
      fdi = (71 + (n - 111)).toString();
      palmerLetter = String.fromCharCode(65 + (n - 111));
      palmerSymbol = '┌';
      borderClass = 'border-t-2 border-l-2';
    } else {
      quadrant = 'LR';
      fdi = (81 + (120 - n)).toString();
      palmerLetter = String.fromCharCode(65 + (120 - n));
      palmerSymbol = '┐';
      borderClass = 'border-t-2 border-r-2';
    }

    return {
      raw: n,
      isChild: true,
      fdi,
      palmerLetter,
      quadrant,
      palmerSymbol,
      borderClass,
      displayFormatted: `${palmerSymbol}${palmerLetter}`,
      fullText: `السن اللبني ${palmerSymbol}${palmerLetter}`
    };
  }

  // 2. Child FDI numbers 51-55, 61-65, 71-75, 81-85
  if (!isNaN(n) && ((n >= 51 && n <= 55) || (n >= 61 && n <= 65) || (n >= 71 && n <= 75) || (n >= 81 && n <= 85))) {
    let quadrant: 'UR' | 'UL' | 'LL' | 'LR' = 'UR';
    let palmerLetter = '';
    let palmerSymbol = '┘';
    let borderClass = 'border-b-2 border-r-2';

    if (n >= 51 && n <= 55) {
      quadrant = 'UR';
      palmerLetter = String.fromCharCode(65 + (n - 51));
      palmerSymbol = '┘';
      borderClass = 'border-b-2 border-r-2';
    } else if (n >= 61 && n <= 65) {
      quadrant = 'UL';
      palmerLetter = String.fromCharCode(65 + (n - 61));
      palmerSymbol = '└';
      borderClass = 'border-b-2 border-l-2';
    } else if (n >= 71 && n <= 75) {
      quadrant = 'LL';
      palmerLetter = String.fromCharCode(65 + (n - 71));
      palmerSymbol = '┌';
      borderClass = 'border-t-2 border-l-2';
    } else {
      quadrant = 'LR';
      palmerLetter = String.fromCharCode(65 + (n - 81));
      palmerSymbol = '┐';
      borderClass = 'border-t-2 border-r-2';
    }

    return {
      raw: n,
      isChild: true,
      fdi: String(n),
      palmerLetter,
      quadrant,
      palmerSymbol,
      borderClass,
      displayFormatted: `${palmerSymbol}${palmerLetter}`,
      fullText: `السن اللبني ${palmerSymbol}${palmerLetter}`
    };
  }

  // 3. Adult FDI numbers (11-18, 21-28, 31-38, 41-48) or explicit FDI formatted strings
  const cleanN = isNaN(n) ? Number(rawStr.replace(/[^0-9]/g, '')) : n;
  if (!isNaN(cleanN) && ((cleanN >= 11 && cleanN <= 18) || (cleanN >= 21 && cleanN <= 28) || (cleanN >= 31 && cleanN <= 38) || (cleanN >= 41 && cleanN <= 48))) {
    let quadrant: 'UR' | 'UL' | 'LL' | 'LR' = 'UR';
    let palmerLetter = '';
    let palmerSymbol = '┘';
    let borderClass = 'border-b-2 border-r-2';

    if (cleanN >= 11 && cleanN <= 18) {
      quadrant = 'UR';
      palmerLetter = (19 - cleanN).toString();
      palmerSymbol = '┘';
      borderClass = 'border-b-2 border-r-2';
    } else if (cleanN >= 21 && cleanN <= 28) {
      quadrant = 'UL';
      palmerLetter = (cleanN - 20).toString();
      palmerSymbol = '└';
      borderClass = 'border-b-2 border-l-2';
    } else if (cleanN >= 31 && cleanN <= 38) {
      quadrant = 'LL';
      palmerLetter = (cleanN - 30).toString();
      palmerSymbol = '┌';
      borderClass = 'border-t-2 border-l-2';
    } else {
      quadrant = 'LR';
      palmerLetter = (cleanN - 40).toString();
      palmerSymbol = '┐';
      borderClass = 'border-t-2 border-r-2';
    }

    return {
      raw: cleanN,
      isChild: false,
      fdi: String(cleanN),
      palmerLetter,
      quadrant,
      palmerSymbol,
      borderClass,
      displayFormatted: `#${cleanN}`,
      fullText: `ضرس #${cleanN}`
    };
  }

  // 4. Adult Universal numbers 1-32 from interactive chart
  if (!isNaN(n) && n >= 1 && n <= 32) {
    let fdi = '';
    let palmerLetter = '';
    let quadrant: 'UR' | 'UL' | 'LL' | 'LR' = 'UR';
    let palmerSymbol = '┘';
    let borderClass = 'border-b-2 border-r-2';

    if (n >= 1 && n <= 8) {
      quadrant = 'UR';
      fdi = (19 - n).toString();
      palmerLetter = (9 - n).toString();
      palmerSymbol = '┘';
      borderClass = 'border-b-2 border-r-2';
    } else if (n >= 9 && n <= 16) {
      quadrant = 'UL';
      fdi = (n + 12).toString();
      palmerLetter = (n - 8).toString();
      palmerSymbol = '└';
      borderClass = 'border-b-2 border-l-2';
    } else if (n >= 17 && n <= 24) {
      quadrant = 'LL';
      fdi = (55 - n).toString();
      palmerLetter = (25 - n).toString();
      palmerSymbol = '┌';
      borderClass = 'border-t-2 border-l-2';
    } else {
      quadrant = 'LR';
      fdi = (n + 16).toString();
      palmerLetter = (n - 24).toString();
      palmerSymbol = '┐';
      borderClass = 'border-t-2 border-r-2';
    }

    return {
      raw: n,
      isChild: false,
      fdi,
      palmerLetter,
      quadrant,
      palmerSymbol,
      borderClass,
      displayFormatted: `#${fdi}`,
      fullText: `ضرس #${fdi}`
    };
  }

  // 4. Direct Palmer letter alone or formatted string
  const letterMatch = rawStr.match(/([┘└┌┐])?\s*([A-Ea-e])\s*([┘└┌┐])?/);
  if (letterMatch) {
    const symbol = letterMatch[1] || letterMatch[3] || '┘';
    const letter = letterMatch[2].toUpperCase();

    let quadrant: 'UR' | 'UL' | 'LL' | 'LR' = 'UR';
    let borderClass = 'border-b-2 border-r-2';

    if (symbol === '└') { quadrant = 'UL'; borderClass = 'border-b-2 border-l-2'; }
    else if (symbol === '┌') { quadrant = 'LL'; borderClass = 'border-t-2 border-l-2'; }
    else if (symbol === '┐') { quadrant = 'LR'; borderClass = 'border-t-2 border-r-2'; }

    return {
      raw: rawStr,
      isChild: true,
      fdi: letter,
      palmerLetter: letter,
      quadrant,
      palmerSymbol: symbol,
      borderClass,
      displayFormatted: `${symbol}${letter}`,
      fullText: `السن اللبني ${symbol}${letter}`
    };
  }

  // 5. Fallback for raw numbers or non-standard strings
  return {
    raw: rawStr,
    isChild: false,
    fdi: rawStr,
    palmerLetter: rawStr,
    quadrant: null,
    palmerSymbol: '',
    borderClass: '',
    displayFormatted: rawStr.startsWith('#') ? rawStr : `#${rawStr}`,
    fullText: rawStr.includes('ضرس') || rawStr.includes('سن') ? rawStr : `ضرس #${rawStr}`
  };
}

export function convertToToothNotation(num: number | string | null | undefined): string {
  if (num === null || num === undefined || num === '') return '';
  const info = getToothInfo(num);
  return info.isChild ? info.displayFormatted : info.fdi;
}

export function convertToFDI(num: number | string | null | undefined): string {
  return convertToToothNotation(num);
}

/**
 * Returns the Universal Chart Number (1-32 for adult, 101-120 for child) for any tooth identifier.
 */
export function getUniversalToothNumber(num: number | string | null | undefined): number | null {
  if (num === null || num === undefined || num === '') return null;
  const rawStr = String(num).trim();
  const n = Number(rawStr);

  if (!isNaN(n)) {
    // Already an adult universal number
    if (n >= 1 && n <= 32) return n;
    // Already a child universal number
    if (n >= 101 && n <= 120) return n;

    // Adult FDI mapping to universal (1-32)
    const fdiToUniversalAdult: Record<number, number> = {
      18: 1, 17: 2, 16: 3, 15: 4, 14: 5, 13: 6, 12: 7, 11: 8,
      21: 9, 22: 10, 23: 11, 24: 12, 25: 13, 26: 14, 27: 15, 28: 16,
      38: 17, 37: 18, 36: 19, 35: 20, 34: 21, 33: 22, 32: 23, 31: 24,
      41: 25, 42: 26, 43: 27, 44: 28, 45: 29, 46: 30, 47: 31, 48: 32
    };
    if (fdiToUniversalAdult[n]) return fdiToUniversalAdult[n];

    // Child FDI mapping to universal (101-120)
    const fdiToUniversalChild: Record<number, number> = {
      55: 101, 54: 102, 53: 103, 52: 104, 51: 105,
      61: 106, 62: 107, 63: 108, 64: 109, 65: 110,
      75: 111, 74: 112, 73: 113, 72: 114, 71: 115,
      81: 116, 82: 117, 83: 118, 84: 119, 85: 120
    };
    if (fdiToUniversalChild[n]) return fdiToUniversalChild[n];
  }

  // Handle Palmer notation or other strings via getToothInfo
  const info = getToothInfo(num);
  if (info && info.fdi) {
    const fdiNum = Number(info.fdi);
    if (!isNaN(fdiNum)) {
      return getUniversalToothNumber(fdiNum);
    }
  }

  return null;
}

/**
 * Returns all possible key representations (Universal, FDI, raw number) for a tooth.
 */
export function getAllToothKeys(num: number | string | null | undefined): number[] {
  if (num === null || num === undefined || num === '') return [];
  const keys = new Set<number>();
  const rawNum = Number(num);
  if (!isNaN(rawNum)) keys.add(rawNum);

  const univ = getUniversalToothNumber(num);
  if (univ !== null) keys.add(univ);

  const info = getToothInfo(num);
  if (info && info.fdi) {
    const fdiNum = Number(info.fdi);
    if (!isNaN(fdiNum)) keys.add(fdiNum);
  }

  return Array.from(keys);
}

export function resolveProcedureBreakdown(app: {
  treatmentType?: string;
  price?: number;
  cost?: number;
  procedures?: any[];
  toothNumber?: number;
}): ProcedureRow[] {
  const totalCost = Number(app.price !== undefined ? app.price : (app.cost || 0));

  let items: Array<{ name: string; tooth: string; explicitPrice: number | null }> = [];

  if (app.procedures && Array.isArray(app.procedures) && app.procedures.length > 0) {
    items = app.procedures.map((p: any) => {
      let cleanName = p.name || 'إجراء طبي';
      let toothNum = '';

      // Check if procedure name contains tooth number in parentheses (e.g. "(ضرس #24)" or "(#24)")
      const parenMatch = cleanName.match(/\((?:ضرس|سن|لبني|السن)?\s*#?\s*([1-8][1-8]|[1-9]\d*|[A-Ea-e])\)/i);
      if (parenMatch) {
        toothNum = convertToToothNotation(parenMatch[1]);
      } else if (p.tooth) {
        toothNum = convertToToothNotation(p.tooth);
      } else if (app.toothNumber) {
        toothNum = convertToToothNotation(app.toothNumber);
      }

      if (cleanName.includes('كشف') || cleanName.includes('استكمال')) {
        toothNum = '';
      }

      if (!toothNum && !cleanName.includes('كشف') && !cleanName.includes('استكمال')) {
        const toothMatch = cleanName.match(/(?:ضرس|سن|لبني|السن|#)\s*#?\s*([1-9]\d*|[A-Ea-e])/i);
        if (toothMatch) {
          toothNum = convertToToothNotation(toothMatch[1]);
        }
      }
      const expPrice = (p.price !== undefined && p.price !== null && !isNaN(Number(p.price)))
        ? Number(p.price)
        : null;
      return {
        name: cleanName,
        tooth: toothNum,
        explicitPrice: expPrice
      };
    });
  } else if (app.treatmentType) {
    const parts = app.treatmentType.split('+').map((p: string) => p.trim()).filter(Boolean);
    items = parts.map((part) => {
      let toothNum = '';

      const parenMatch = part.match(/\((?:ضرس|سن|لبني|السن)?\s*#?\s*([1-8][1-8]|[1-9]\d*|[A-Ea-e])\)/i);
      if (parenMatch) {
        toothNum = convertToToothNotation(parenMatch[1]);
      } else if (app.toothNumber) {
        toothNum = convertToToothNotation(app.toothNumber);
      }

      if (part.includes('كشف') || part.includes('استكمال')) {
        toothNum = '';
      }

      if (!toothNum && !part.includes('كشف') && !part.includes('استكمال')) {
        const toothMatch = part.match(/(?:ضرس|سن|لبني|السن|#)\s*#?\s*([1-9]\d*|[A-Ea-e])/i);
        if (toothMatch) {
          toothNum = convertToToothNotation(toothMatch[1]);
        }
      }
      return {
        name: part,
        tooth: toothNum,
        explicitPrice: parts.length === 1 ? totalCost : null
      };
    });
  } else {
    items = [{
      name: 'جلسة علاجية',
      tooth: app.toothNumber ? convertToToothNotation(app.toothNumber) : '',
      explicitPrice: totalCost
    }];
  }

  const allHavePrice = items.every(i => i.explicitPrice !== null);
  if (allHavePrice) {
    const sumExplicit = items.reduce((acc, i) => acc + (i.explicitPrice || 0), 0);
    if (items.length === 1 || sumExplicit === totalCost || totalCost === 0) {
      return items.map(i => ({
        name: i.name,
        tooth: i.tooth,
        price: i.explicitPrice || 0
      }));
    }
  }

  if (totalCost === 0) {
    return items.map(i => ({
      name: i.name,
      tooth: i.tooth,
      price: i.explicitPrice !== null ? i.explicitPrice : 0
    }));
  }

  const estimates = items.map(i => {
    if (i.explicitPrice !== null && i.explicitPrice > 0) return i.explicitPrice;
    for (const [key, val] of Object.entries(STANDARD_EGP_PRICES)) {
      if (i.name.includes(key) || key.includes(i.name)) {
        return val;
      }
    }
    return 300;
  });

  const sumEstimates = estimates.reduce((a, b) => a + b, 0);

  let accumulated = 0;
  return items.map((item, idx) => {
    let assignedPrice: number;
    if (idx === items.length - 1) {
      assignedPrice = Math.max(0, totalCost - accumulated);
    } else {
      const ratio = sumEstimates > 0 ? estimates[idx] / sumEstimates : 1 / items.length;
      assignedPrice = Math.round(totalCost * ratio);
      accumulated += assignedPrice;
    }
    return {
      name: item.name,
      tooth: item.tooth,
      price: assignedPrice
    };
  });
}

export function resizeImageToWidth190(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        // High density / Retina sizing for a highly-visible and crisp larger layout
        const MAX_WIDTH = 800; 
        const MAX_HEIGHT = 320;

        // Auto-trim transparent or solid white edges/borders around the actual logo
        let srcElement: HTMLImageElement | HTMLCanvasElement = img;
        try {
          const trimCanvas = document.createElement('canvas');
          trimCanvas.width = img.width;
          trimCanvas.height = img.height;
          const trimCtx = trimCanvas.getContext('2d');
          if (trimCtx) {
            trimCtx.drawImage(img, 0, 0);
            const imgData = trimCtx.getImageData(0, 0, trimCanvas.width, trimCanvas.height);
            const data = imgData.data;

            let minX = trimCanvas.width;
            let maxX = 0;
            let minY = trimCanvas.height;
            let maxY = 0;

            // Find boundaries of actual content (non-transparent, non-white)
            for (let y = 0; y < trimCanvas.height; y++) {
              for (let x = 0; x < trimCanvas.width; x++) {
                const index = (y * trimCanvas.width + x) * 4;
                const r = data[index];
                const g = data[index + 1];
                const b = data[index + 2];
                const alpha = data[index + 3];

                const isTransparent = alpha < 12;
                const isWhite = r > 248 && g > 248 && b > 248;

                if (!isTransparent && !isWhite) {
                  if (x < minX) minX = x;
                  if (x > maxX) maxX = x;
                  if (y < minY) minY = y;
                  if (y > maxY) maxY = y;
                }
              }
            }

            // If a valid boundary was found, crop/trim the image
            if (maxX >= minX && maxY >= minY) {
              const pad = 4; // Add tiny padding so it doesn't touch the edges completely
              minX = Math.max(0, minX - pad);
              minY = Math.max(0, minY - pad);
              maxX = Math.min(trimCanvas.width - 1, maxX + pad);
              maxY = Math.min(trimCanvas.height - 1, maxY + pad);

              const cropW = maxX - minX + 1;
              const cropH = maxY - minY + 1;

              const cropCanvas = document.createElement('canvas');
              cropCanvas.width = cropW;
              cropCanvas.height = cropH;
              const cropCtx = cropCanvas.getContext('2d');
              if (cropCtx) {
                cropCtx.drawImage(trimCanvas, minX, minY, cropW, cropH, 0, 0, cropW, cropH);
                srcElement = cropCanvas;
              }
            }
          }
        } catch (err) {
          console.warn('Trim logic skipped:', err);
          srcElement = img;
        }

        let width = srcElement.width;
        let height = srcElement.height;

        // Calculate aspect-ratio preserving dimensions
        if (width > MAX_WIDTH || height > MAX_HEIGHT) {
          const ratio = Math.min(MAX_WIDTH / width, MAX_HEIGHT / height);
          width = Math.round(width * ratio);
          height = Math.round(height * ratio);
        }

        // Create the high-quality target canvas
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');

        if (!ctx) {
          resolve(e.target?.result as string);
          return;
        }

        // Implement step-down (staged downsampling) to prevent aliasing/pixelation
        let tempCanvas = document.createElement('canvas');
        let tempCtx = tempCanvas.getContext('2d');
        
        if (tempCtx && srcElement.width > width * 2) {
          let curWidth = srcElement.width;
          let curHeight = srcElement.height;
          
          tempCanvas.width = curWidth;
          tempCanvas.height = curHeight;
          tempCtx.drawImage(srcElement, 0, 0);
          
          // Downsample by 50% steps
          while (curWidth > width * 2) {
            const nextWidth = Math.round(curWidth / 2);
            const nextHeight = Math.round(curHeight / 2);
            
            const stepCanvas = document.createElement('canvas');
            stepCanvas.width = nextWidth;
            stepCanvas.height = nextHeight;
            const stepCtx = stepCanvas.getContext('2d');
            
            if (stepCtx) {
              stepCtx.imageSmoothingEnabled = true;
              stepCtx.imageSmoothingQuality = 'high';
              stepCtx.drawImage(tempCanvas, 0, 0, curWidth, curHeight, 0, 0, nextWidth, nextHeight);
              
              tempCanvas = stepCanvas;
              tempCtx = stepCtx;
              curWidth = nextWidth;
              curHeight = nextHeight;
            } else {
              break;
            }
          }
          
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(tempCanvas, 0, 0, curWidth, curHeight, 0, 0, width, height);
        } else {
          // Standard high-quality single-step downsample or upsample
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'high';
          ctx.drawImage(srcElement, 0, 0, width, height);
        }

        // Convert to high-quality PNG to preserve transparency
        resolve(canvas.toDataURL('image/png', 1.0));
      };
      img.onerror = () => {
        reject(new Error('Failed to load image'));
      };
      img.src = e.target?.result as string;
    };
    reader.onerror = () => {
      reject(new Error('Failed to read file'));
    };
    reader.readAsDataURL(file);
  });
}

